const base='/api/lounge/v2/stage-bridge/curated';
export const curatedConsoleStyle=`:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:var(--void);color:var(--text-high);font:16px/1.55 system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:28px 24px 64px}h1{font-size:clamp(28px,5vw,42px);line-height:1.15}h2{font-size:22px}p{max-width:76ch}a{color:var(--cyan)}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--cyan);outline-offset:3px}article,section,.notice{border:1px solid var(--ridge);background:var(--panel);border-radius:16px;padding:22px;margin:24px 0}.notice{border-color:var(--gold)}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}button,input{font:inherit}button,.actions a{min-height:44px;padding:10px 16px;border:1px solid var(--text-faint);border-radius:8px;background:var(--panel);color:var(--text-high)}button:disabled{opacity:.5}fieldset{border:0;padding:0;margin:0;min-width:0}label{display:block;margin:16px 0 8px}input[type=text]{display:block;width:100%;padding:12px;border:1px solid var(--text-faint);border-radius:8px;background:var(--void);color:var(--text-high)}.consent{display:flex;gap:12px;align-items:flex-start;min-height:44px}.consent input{width:22px;height:22px;flex:none;margin-top:3px}img{display:block;max-width:100%;max-height:420px;margin:16px auto;object-fit:contain;border-radius:8px;background:var(--void)}dl{display:grid;grid-template-columns:minmax(100px,180px) minmax(0,1fr);gap:8px 16px}dt{color:var(--text-mid)}dd{margin:0;overflow-wrap:anywhere}.hash{font-family:var(--font-mono);font-size:13px;overflow-wrap:anywhere}#status{min-height:3em;color:var(--text-mid)}small{color:var(--text-mid)}[hidden]{display:none!important}@media(max-width:520px){main{padding:20px 16px 48px}article,section,.notice{padding:18px}.actions{align-items:stretch}.actions>*{max-width:100%}dl{grid-template-columns:1fr;gap:4px}dd{margin-bottom:10px}}`;
export function curatedConsoleHtml({csrf,sessionKey,ownerKey}={}){
 if(typeof csrf!=='string'||!/^[A-Za-z0-9_-]{16,128}$/.test(csrf)||typeof sessionKey!=='string'||!/^[a-f0-9]{64}$/.test(sessionKey)||typeof ownerKey!=='string'||!/^[a-f0-9]{64}$/.test(ownerKey))throw Error('Invalid curated console context');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf" content="${csrf}"><meta name="curated-session" content="${sessionKey}"><meta name="curated-owner" content="${ownerKey}"><title>CUHZ Lounge — Owner-curated artwork</title><link rel="stylesheet" href="/api/lounge/v2/stage/tokens.css"><link rel="stylesheet" href="${base}/console.css"></head><body><main><p>PLANET CUHZ · PRIVATE OWNER WORKSPACE</p><h1>Owner-curated artwork</h1><p>Prepare the existing Planet CUHZ brand image privately, inspect the exact preview, then request publication review. This does not generate artwork or start the show.</p><aside class="notice"><strong>Keep the stage on hold while preparing publication.</strong><p>Approved artwork can enter the scheduled showcase automatically. Use stage controls to hold the stage before importing or requesting review, and keep it held through the separate approval step.</p><div class="actions"><a href="/api/lounge/v2/stage/ops">Open stage controls</a><a href="/api/lounge/v2/stage/ops/emergency">Emergency hold</a></div><p id="hold-state">Checking stage hold…</p></aside><div class="actions"><button id="refresh" type="button">Refresh private status</button><button id="stop" type="button">Stop and clear preview</button></div><p id="status" role="status" aria-live="polite">Checking the current owner session…</p><section aria-labelledby="catalog-heading"><h2 id="catalog-heading">1. Prepare a private candidate</h2><p id="catalog-title">The server-approved catalog is loading.</p><dl><dt>Catalog revision</dt><dd id="catalog-revision">—</dd><dt>Original SHA-256</dt><dd id="catalog-hash" class="hash">—</dd><dt>Public origin label</dt><dd>Owner-curated artwork</dd></dl><p>Import saves the original and a verified preview privately. It does not claim who made the image, grant rights, or approve publication.</p><button id="import" type="button" disabled>Import brand image privately</button></section><article id="candidate" hidden aria-labelledby="candidate-heading"><h2 id="candidate-heading">2. Inspect and request review</h2><p id="item-status"></p><div id="preview"></div><p id="preview-state">Preview is unavailable.</p><dl><dt>Original SHA-256</dt><dd id="original-hash" class="hash"></dd><dt>Preview SHA-256</dt><dd id="preview-hash" class="hash"></dd><dt>Item revision</dt><dd id="item-revision"></dd></dl><fieldset id="consent-fields" disabled><label for="public-title">Public title</label><input id="public-title" type="text" maxlength="100" autocomplete="off"><label for="public-attribution">Presented by</label><input id="public-attribution" type="text" maxlength="40" autocomplete="off"><p>The stage will say <strong>Owner-curated artwork</strong> and <strong>Presented by</strong>. Attribution does not assert authorship.</p><label class="consent"><input id="adult" type="checkbox">I confirm I am 18 or older.</label><label class="consent"><input id="rights" type="checkbox">I have the rights and permission needed to display this exact artwork publicly with this title and attribution.</label><label class="consent"><input id="publication" type="checkbox">I consent to public display of this exact image and metadata after a separate review approval.</label><button id="submit" type="button" disabled>Request publication review</button></fieldset><p><small>Changing the title, attribution, image, or item revision clears these confirmations.</small></p><section aria-labelledby="withdraw-heading"><h3 id="withdraw-heading">Withdraw public display</h3><p>Withdraw publication consent for this item, including a pending review or approved publication. The private original stays in your library. This action does not require new age or rights confirmations, a loaded preview, or a stage hold.</p><button id="withdraw" type="button" disabled>Withdraw publication consent</button><p><small>Changing workflow flags does not withdraw publication consent. Emergency hold can pause the stage while you resolve an uncertain withdrawal.</small></p></section></article><section id="recovery" hidden aria-labelledby="recovery-heading"><h2 id="recovery-heading">Resolve the pending operation</h2><p id="recovery-copy">The outcome is unknown. No new operation can start. Recover deliberately using the same saved receipt and exact request.</p><p id="recovery-summary"></p><p>Receipt: <span id="receipt" class="hash"></span></p><button id="recover" type="button" disabled>Recover the same operation</button></section><section><h2>3. Make a separate review decision</h2><p>Requesting review does not approve or publish the image. Inspect it again in the protected review queue and choose an approval or rejection reason. Keep the stage held until you are ready for an attended reveal.</p><a href="/api/lounge/v2/stage-bridge/ops">Open artwork review queue</a></section></main><script src="${base}/console.js" defer></script></body></html>`;
}
export const curatedConsoleScript=String.raw`'use strict';
const base='/api/lounge/v2/stage-bridge/curated',q=id=>document.querySelector('#'+id);
const csrf=document.querySelector('meta[name=csrf]').content,sessionKey=document.querySelector('meta[name=curated-session]').content,ownerKey=document.querySelector('meta[name=curated-owner]').content;
const storageKey='cuhz-owner-curated-pending-v1',hash=/^[a-f0-9]{64}$/,uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const controllers=new Set();let epoch=0,imageEpoch=0,busy=false,locked=false,current=null,previewReady=false,pending=null;
const clean=(value,max)=>typeof value==='string'&&value.trim().length>0&&value.length<=max&&!/[\x00-\x1f\x7f]/.test(value);
const active=run=>!locked&&run===epoch;
function clearConsent(){for(const id of ['adult','rights','publication'])q(id).checked=false;}
function itemKey(item){return item?[item.id,item.revision,item.canonicalHash,item.derivativeHash,item.catalogRevision,item.status,item.title,item.displayName].join(':'):'';}
function allow(){const ready=!locked&&!busy;const held=current?.stageHeld===true;const editable=ready&&!pending&&held&&previewReady&&['private','rejected'].includes(current?.item?.status);q('refresh').disabled=!ready;q('stop').disabled=locked;q('import').disabled=!(ready&&!pending&&held&&current&&!current.item);q('consent-fields').disabled=!editable;q('submit').disabled=!(editable&&clean(q('public-title').value,100)&&clean(q('public-attribution').value,40)&&['adult','rights','publication'].every(id=>q(id).checked));q('withdraw').disabled=!(ready&&!pending&&current?.item&&['in_review','approved','rejected'].includes(current.item.status));q('recover').disabled=!(ready&&pending&&current);q('recovery').hidden=!pending||!current;q('receipt').textContent=pending&&current?pending.payload.requestId:'';q('recovery-summary').textContent=pending&&current?(pending.action==='import'?'Private import: '+pending.payload.catalogKey:pending.action==='revoke'?'Withdraw publication consent for item '+pending.payload.itemId:'Saved review request: '+pending.payload.title+' · Presented by '+pending.payload.displayName+' · Item revision '+pending.payload.expectedRevision):'';}
function forget(){pending=null;try{sessionStorage.removeItem(storageKey);}catch{}allow();}
function invalidate(message){if(locked)return;locked=true;epoch++;imageEpoch++;for(const controller of controllers)controller.abort();controllers.clear();current=null;previewReady=false;pending=null;clearConsent();q('public-title').value='';q('public-attribution').value='';for(const id of ['original-hash','preview-hash','item-revision','item-status'])q(id).textContent='';q('preview').replaceChildren();q('candidate').hidden=true;q('catalog-title').textContent='Private context cleared.';q('catalog-revision').textContent='—';q('catalog-hash').textContent='—';q('hold-state').textContent='Stage state is unavailable.';q('status').textContent=message;allow();}
function savedAttempt(value){if(!value||value.ownerKey!==ownerKey||!hash.test(value.sessionKey)||!['import','review','revoke'].includes(value.action)||!value.payload||!uuid.test(value.payload.requestId))return false;const p=value.payload;return value.action==='import'?Object.keys(p).sort().join(',')==='catalogKey,requestId'&&p.catalogKey==='planet-cuhz-logo-v1':value.action==='revoke'?Object.keys(p).sort().join(',')==='itemId,requestId'&&uuid.test(p.itemId):Object.keys(p).sort().join(',')==='adultConfirmed,consent,displayName,expectedRevision,itemId,requestId,rightsConfirmed,title'&&uuid.test(p.itemId)&&Number.isSafeInteger(p.expectedRevision)&&p.expectedRevision>0&&clean(p.title,100)&&clean(p.displayName,40)&&p.adultConfirmed===true&&p.rightsConfirmed===true&&p.consent===true;}
function persist(attempt){sessionStorage.setItem(storageKey,JSON.stringify(attempt));pending=attempt;}
async function request(path,options,run){const controller=new AbortController();controllers.add(controller);let timer;try{return await Promise.race([(async()=>{const response=await fetch(path==='/publication/revoke'?'/api/lounge/v2/stage-bridge/publication/revoke':base+path,{credentials:'same-origin',cache:'no-store',...options,signal:controller.signal});if(!active(run))throw Error('CANCELLED');let data;try{data=await response.json();}catch{throw Error('UNAVAILABLE');}if(!active(run))throw Error('CANCELLED');if(response.status===401||response.status===403)throw Error('SESSION_CHANGED');if(!response.ok||data?.ok===false){if(response.status>=500||data?.error==='BRIDGE_OUTCOME_UNKNOWN')throw Error('UNAVAILABLE');throw Error(data?.code==='STAGE_HOLD_REQUIRED'||data?.error==='STAGE_HOLD_REQUIRED'?'HOLD_REQUIRED':'REFUSED');}return data;})(),new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error('UNAVAILABLE'));},8000);})]);}finally{clearTimeout(timer);controllers.delete(controller);}}
function validated(data){if(data?.sessionKey!==sessionKey||data?.ownerKey!==ownerKey)throw Error('SESSION_CHANGED');const c=data.catalog,i=data.item;if(!c||c.key!=='planet-cuhz-logo-v1'||!clean(c.revision,32)||!clean(c.title,100)||!hash.test(c.sha256)||c.label!=='owner_curated'||c.width!==1024||c.height!==1024||typeof data.stageHeld!=='boolean')throw Error('UNAVAILABLE');if(i&&(!uuid.test(i.id)||!Number.isSafeInteger(i.revision)||i.revision<1||!hash.test(i.canonicalHash)||!hash.test(i.derivativeHash)||i.canonicalHash!==c.sha256||i.catalogKey!==c.key||i.catalogRevision!==c.revision||i.previewUrl!==base+'/items/'+i.id+'/image'||!['private','in_review','approved','rejected','withdrawn'].includes(i.status)))throw Error('UNAVAILABLE');return data;}
async function context(run){return validated(await request('',{},run));}
function render(data){const previous=itemKey(current?.item);if(current&&current.stageHeld!==data.stageHeld)clearConsent();current=data;const item=data.item;q('catalog-title').textContent=data.catalog.title;q('catalog-revision').textContent=data.catalog.revision;q('catalog-hash').textContent=data.catalog.sha256;q('hold-state').textContent=data.stageHeld?'Stage is currently held. Keep it held through the separate review decision.':'Stage is not held. Open stage controls, apply hold, then refresh here.';q('candidate').hidden=!item;if(!item){previewReady=false;clearConsent();q('preview').replaceChildren();allow();return;}q('item-status').textContent='Current item status: '+item.status.replaceAll('_',' ')+'.';q('original-hash').textContent=item.canonicalHash;q('preview-hash').textContent=item.derivativeHash;q('item-revision').textContent=String(item.revision);if(previous===itemKey(item)){allow();return;}previewReady=false;clearConsent();q('public-title').value=clean(item.title,100)?item.title:data.catalog.title;q('public-attribution').value=clean(item.displayName,40)?item.displayName:'Planet CUHZ';q('preview-state').textContent='Loading the private verified preview…';const image=document.createElement('img'),run=epoch,imageRun=++imageEpoch,key=itemKey(item);image.alt='Private preview: '+data.catalog.title;image.onload=async()=>{try{await image.decode();if(!active(run)||imageRun!==imageEpoch)return;const fresh=await context(run);if(!active(run)||imageRun!==imageEpoch)return;if(itemKey(fresh.item)!==key){clearConsent();render(fresh);q('status').textContent='The candidate changed. Inspect the new preview and confirm again.';return;}current=fresh;previewReady=true;q('hold-state').textContent=fresh.stageHeld?'Stage is currently held. Keep it held through the separate review decision.':'Stage is not held. Open stage controls, apply hold, then refresh here.';q('preview-state').textContent='Verified private preview loaded. Review the hashes, title, and attribution before confirming.';allow();}catch(error){if(!active(run)||imageRun!==imageEpoch)return;if(error.message==='SESSION_CHANGED')invalidate('Your owner session changed or is unavailable. Private data was cleared. Reload after signing in.');else{previewReady=false;clearConsent();q('preview').replaceChildren();q('preview-state').textContent='Preview unavailable. Refresh deliberately to try again.';allow();}}};image.onerror=()=>{if(active(run)&&imageRun===imageEpoch){previewReady=false;clearConsent();q('preview').replaceChildren();q('preview-state').textContent='Preview unavailable. Refresh deliberately to try again.';allow();}};q('preview').replaceChildren(image);image.src=item.previewUrl;allow();}
async function load(){if(busy||locked)return;busy=true;allow();const run=epoch;try{const data=await context(run);if(!active(run))return;const changed=itemKey(current?.item)!==itemKey(data.item);if(!changed&&data.item&&!previewReady)current=null;render(data);q('status').textContent=pending?'A saved operation needs recovery. Refreshing made no changes. Use Recover the same operation deliberately.':data.item?'Inspect the private candidate. Publication requires explicit consent and a separate review decision.':'The fixed brand image is available to import privately.';}catch(error){if(!active(run))return;if(error.message==='SESSION_CHANGED')invalidate('Your owner session changed or is unavailable. Private data was cleared. Reload after signing in.');else{previewReady=false;clearConsent();q('preview').replaceChildren();q('candidate').hidden=true;q('status').textContent='Private status is unavailable. Refresh deliberately to try again; no operation was started.';}}finally{if(active(run)){busy=false;allow();}}}
async function operate(attempt,recovering=false){if(busy||locked||(!recovering&&pending))return;const run=epoch,expected=itemKey(current?.item);let sent=false;try{persist(attempt);}catch{q('status').textContent='Receipt storage is unavailable. Nothing was sent. Enable session storage and reload before continuing.';return;}busy=true;clearConsent();allow();q('status').textContent=recovering?'Recovering the exact saved operation…':'Rechecking the current owner session and stage hold…';try{const fresh=await context(run);if(!active(run))return;if(!fresh.stageHeld&&!recovering&&attempt.action!=='revoke'){render(fresh);throw Error('HOLD_REQUIRED');}if(!recovering&&(attempt.action==='import'?!!fresh.item:attempt.action==='revoke'?fresh.item?.id!==attempt.payload.itemId:itemKey(fresh.item)!==expected||fresh.item?.revision!==attempt.payload.expectedRevision)){forget();render(fresh);q('status').textContent='The candidate changed. Inspect the current preview and confirm again.';return;}sent=true;const result=await request(attempt.action==='revoke'?'/publication/revoke':'/'+attempt.action,{method:'POST',headers:{'Content-Type':'application/json','X-Lounge-CSRF':csrf},body:JSON.stringify(attempt.payload)},run);if(result?.ok!==true)throw Error('UNAVAILABLE');const refreshed=await context(run);if(!active(run))return;forget();render(refreshed);q('status').textContent=recovering?'The saved operation is resolved. Current private status has been refreshed. Recovery does not approve or republish artwork.':attempt.action==='revoke'?(refreshed.item?.status==='private'?'Publication consent withdrawn. The private original is retained.':'Withdrawal receipt recorded. Current item status: '+(refreshed.item?.status||'unavailable')+'. Refresh to inspect its latest status.'):attempt.action==='import'?'Imported privately. Nothing was submitted or approved. Inspect the exact preview before requesting review.':'Review request recorded. Approval is a separate action in the artwork review queue. Keep the stage held.';}catch(error){if(!active(run))return;if(error.message==='SESSION_CHANGED'){invalidate('Your owner session changed or is unavailable. Private data was cleared. Reload after signing in.');return;}if(sent&&error.message==='UNAVAILABLE'){q('status').textContent='Outcome unknown. The same receipt and exact request were saved. Do not start another operation; use deliberate recovery.';}else if(recovering){q('status').textContent=error.message==='HOLD_REQUIRED'?'Keep the stage held, then refresh and recover this same operation.':'Recovery was refused or unavailable. The original receipt is retained; no new operation can start.';}else{forget();q('status').textContent=error.message==='HOLD_REQUIRED'?'The stage must be held. Open stage controls, then refresh before trying again.':sent?'The request was refused. Refresh and inspect the current candidate before trying again.':'The session or candidate could not be rechecked. Nothing was sent. Refresh deliberately to try again.';}}finally{if(active(run)){busy=false;allow();}}}
q('refresh').onclick=load;q('stop').onclick=()=>invalidate('Stopped. Private preview and confirmations were cleared. Reload this page to continue.');
q('import').onclick=()=>{if(q('import').disabled)return;operate({ownerKey,sessionKey,action:'import',payload:{requestId:crypto.randomUUID(),catalogKey:current.catalog.key}});};
q('submit').onclick=()=>{if(q('submit').disabled)return;operate({ownerKey,sessionKey,action:'review',payload:{requestId:crypto.randomUUID(),itemId:current.item.id,expectedRevision:current.item.revision,title:q('public-title').value.trim(),displayName:q('public-attribution').value.trim(),consent:true,adultConfirmed:true,rightsConfirmed:true}});};
q('withdraw').onclick=()=>{if(q('withdraw').disabled)return;operate({ownerKey,sessionKey,action:'revoke',payload:{requestId:crypto.randomUUID(),itemId:current.item.id}});};
q('recover').onclick=()=>{if(q('recover').disabled||!pending)return;operate(pending,true);};
for(const id of ['public-title','public-attribution'])q(id).oninput=()=>{clearConsent();allow();};for(const id of ['adult','rights','publication'])q(id).onchange=allow;
window.addEventListener('pagehide',()=>invalidate('Private preview cleared. Reload to continue.'),{once:true});
try{const raw=sessionStorage.getItem(storageKey);if(raw){const value=JSON.parse(raw);if(value?.ownerKey!==ownerKey)throw Error('OTHER_OWNER');if(!savedAttempt(value))throw Error('INVALID_RECEIPT');pending=value;}}catch(error){locked=true;q('status').textContent=error.message==='OTHER_OWNER'?'A pending operation belongs to another owner context. Private details are hidden. Recover it with the original owner before starting another operation.':'Saved receipt data is unavailable or invalid. No operation can start in this page. Contact the owner before clearing session data.';}
allow();if(!locked)load();
`;
